function finishReview() {
  reviewSession.hidden=true;reviewComplete.hidden=false;const values=Object.values(reviewResults);const entries=reviewQueue.map(key=>state.vocabulary[key]).filter(Boolean);
  const count=status=>values.filter(x=>x===status).length;reviewSummary.textContent=`本轮复习总数：${reviewQueue.length}\n陌生：${count("unfamiliar")} · 学习中：${count("learning")} · 已掌握：${count("mastered")}\n单词：${entries.filter(x=>x.type!=="phrase").length} · 短语：${entries.filter(x=>x.type==="phrase").length}`;
}
