dataManagementButton.addEventListener("click",openDataPanel);dataPanelClose.addEventListener("click",closeDataPanel);dataBackdrop.addEventListener("click",closeDataPanel);
exportDataButton.addEventListener("click",()=>{try{const json=backupJSON();if(typeof Blob!=="undefined"&&globalThis.URL?.createObjectURL){const blob=new Blob([json],{type:"application/json;charset=utf-8"});const link=document.createElement("a");link.href=URL.createObjectURL(blob);link.download=formatBackupName();document.body.append(link);link.click();link.remove?.();URL.revokeObjectURL(link.href)}writeBackupMeta({lastExportAt:now()});renderDataPanel();setDataStatus("全部数据已成功导出。若浏览器未下载，可使用“复制备份 JSON”。")}catch{setDataStatus("导出失败，请检查浏览器存储或使用复制功能。","error")}});
copyBackupButton.addEventListener("click",async()=>{const json=backupJSON();try{if(globalThis.navigator?.clipboard?.writeText)await globalThis.navigator.clipboard.writeText(json);else{backupText.value=json;backupText.select?.();if(!document.execCommand?.("copy"))throw new Error()}writeBackupMeta({lastExportAt:now()});renderDataPanel();setDataStatus("完整备份 JSON 已复制。") }catch{backupText.value=json;setDataStatus("浏览器未允许自动复制，完整 JSON 已放入文本框，请手动复制。","error")}});
previewBackupButton.addEventListener("click",()=>{try{previewBackup(backupText.value)}catch(error){pendingBackup=null;backupPreview.hidden=true;setDataStatus(error.message,"error")}});
backupFile.addEventListener("change",()=>{const file=backupFile.files?.[0];if(!file)return;if(!file.name.toLowerCase().endsWith(".json")){setDataStatus("请选择 .json 备份文件。","error");return}const reader=new FileReader();reader.onload=()=>{backupText.value=String(reader.result||"");try{previewBackup(backupText.value)}catch(error){pendingBackup=null;backupPreview.hidden=true;setDataStatus(error.message,"error")}};reader.onerror=()=>setDataStatus("无法读取所选文件，请重新选择。","error");reader.readAsText(file,"UTF-8")});
confirmImportButton.addEventListener("click",()=>{if(!pendingBackup){setDataStatus("请先验证并预览备份。","error");return}const selected=document.querySelector('input[name="importMode"]:checked');const mode=selected?.value||"merge";if(mode==="replace"&&(!window.confirm("覆盖导入会使用备份替换当前应用数据。是否继续？")||!window.confirm("请再次确认：覆盖前会保存可撤销快照，确定替换吗？")))return;try{if(mode==="merge"){const merged=mergeLibrary(pendingBackup.library);commitImport(merged.result,merged.summary,pendingBackup.oldVersion)}else{const next=validateLibrary(pendingBackup.library);const c=dataCounts(next);commitImport(next,{addedArticles:c.articles,skippedArticles:0,addedWords:c.words,addedPhrases:c.phrases,mergedRelations:0,renamedArticles:0},pendingBackup.oldVersion)}}catch(error){setDataStatus(error.message||"导入失败，现有数据没有改变。","error")}});
undoImportButton.addEventListener("click",()=>{if(!window.confirm("撤销会恢复最近一次导入前的数据，是否继续？")||!window.confirm("请再次确认恢复导入前快照。"))return;try{const snapshot=JSON.parse(localStorage.getItem(IMPORT_SNAPSHOT_KEY));const restored=validateLibrary(snapshot?.library);localStorage.setItem(STORAGE_KEY,JSON.stringify(restored));state=restored;localStorage.removeItem(IMPORT_SNAPSHOT_KEY);fillEditor(currentUnit());renderLibrary();renderVocabulary();renderDataPanel();setDataStatus("已撤销最近一次导入并恢复原数据。")}catch{setDataStatus("撤销失败，当前数据没有改变。","error")}});
function openArticleVocabulary(id){articleVocabularyId=id;articleVocabularyFilter="all";articleVocabularyStatusFilter="all";libraryItems.hidden=true;libraryEmpty.hidden=true;newArticleButton.hidden=true;saveArticleButton.hidden=true;articleVocabulary.hidden=false;libraryTitle.textContent="本篇词汇";[...articleVocabularyFilters.querySelectorAll("button")].forEach(button=>button.setAttribute("aria-pressed",String(button.dataset.filter==="all")));[...articleVocabularyStatusFilters.querySelectorAll("button")].forEach(button=>button.setAttribute("aria-pressed",String(button.dataset.status==="all")));renderArticleVocabulary();articleVocabularyBack.focus();}
articleVocabularyBack.addEventListener("click",()=>{renderLibrary();showLibraryList();});
articleVocabularyFilters.addEventListener("click",e=>{const button=e.target.closest("button[data-filter]");if(!button)return;articleVocabularyFilter=button.dataset.filter;[...articleVocabularyFilters.querySelectorAll("button")].forEach(item=>item.setAttribute("aria-pressed",String(item===button)));renderArticleVocabulary();});
articleVocabularyItems.addEventListener("click",e=>{const remove=e.target.closest("button[data-action]");if(remove?.dataset.action==="remove-vocabulary"){const entry=state.vocabulary[remove.dataset.key];if(!entry||!window.confirm(`确定从本篇移除“${entry.text}”吗？这不会从总词汇表删除。`))return;entry.sources=(entry.sources||[]).filter(item=>item.articleId!==articleVocabularyId);if(!entryArticleIds(entry).length&&window.confirm("该词汇已没有任何文章来源。是否从总词汇表彻底删除？取消将默认保留。"))delete state.vocabulary[remove.dataset.key];saveState();renderArticleVocabulary();renderLibrary();renderVocabulary();return;}const item=e.target.closest(".vocabulary-item");if(item)openCard(item.dataset.key,item);});
libraryItems.addEventListener("click",e=>{const b=e.target.closest("button[data-action]");if(!b)return;const unit=state.articles.find(x=>x.id===b.dataset.id);if(!unit)return;if(b.dataset.action==="open")openUnit(unit.id);if(b.dataset.action==="vocabulary")openArticleVocabulary(unit.id);if(b.dataset.action==="rename"){const name=window.prompt("输入新的学习单元标题",unit.articleTitle);if(name?.trim()){unit.articleTitle=name.trim();unit.updatedAt=now();if(unit.id===state.currentId)articleTitle.value=unit.articleTitle;saveState();renderLibrary();}}if(b.dataset.action==="delete"){if(!window.confirm(`确定删除“${unit.articleTitle}”吗？文章关联会解除，但词汇默认保留。`))return;const exclusive=Object.entries(state.vocabulary).filter(([,entry])=>isEntryInArticle(entry,unit.id)&&entryArticleIds(entry).length===1);const deleteExclusive=exclusive.length&&window.confirm(`有 ${exclusive.length} 个词汇只来源于此文章。是否一并从总词汇表删除？取消将默认保留为“未归属文章”。`);Object.entries(state.vocabulary).forEach(([key,entry])=>{if(deleteExclusive&&exclusive.some(([exclusiveKey])=>exclusiveKey===key)){delete state.vocabulary[key];return;}entry.sources=(entry.sources||[]).filter(item=>item.articleId!==unit.id);});state.articles=state.articles.filter(x=>x.id!==unit.id);if(state.currentId===unit.id){state.currentId=state.articles[0]?.id||null;fillEditor(currentUnit());}saveState();renderLibrary();renderVocabulary();}});
window.addEventListener?.("scroll",()=>{const unit=currentUnit();if(!readerView.hidden&&unit){unit.lastScrollY=window.scrollY||0;saveState();}},{passive:true});
document.addEventListener("keydown",e=>{if(!reviewPanel.hidden){if((e.key==="Enter"||e.key===" ")&&!reviewRevealed){e.preventDefault();revealReviewAnswer();return}if(e.key==="ArrowLeft"){e.preventDefault();goReview(-1);return}if(e.key==="ArrowRight"){e.preventDefault();goReview(1);return}}if(e.key==="Escape"){if(!gptCopyPanel.hidden)closeGptCopyPanel();else if(!reviewPanel.hidden)closeReview();else if(!wordCard.hidden)closeCard();else if(!libraryPanel.hidden)closeLibrary();else if(!dataPanel.hidden)closeDataPanel();else if(phraseMode)setPhraseMode(false);}});

migrateLegacy();fillEditor(currentUnit());renderLibrary();renderVocabulary();
